INSERT INTO `reading_question` VALUES (1,1,1,'There are other parrots that share the kakapo\'s inability to fly.',NULL,'FALSE',1),(2,1,1,'Adult kakapo produce chicks every year.',NULL,'FALSE',2),(3,1,1,'Adult male kakapo bring food back to nesting females.',NULL,'FALSE',3),(4,1,1,'The Polynesian rat was a greater threat to the kakapo than Polynesian settlers.',NULL,'NOT GIVEN',4),(5,1,1,'Kakapo were transferred from Rakiura Island to other locations because they were at risk from feral cats.',NULL,'TRUE',5),(6,1,1,'One Recovery Plan initiative that helped increase the kakapo population size was caring for struggling young birds.',NULL,'TRUE',6),(7,2,8,'diet consists of fern fronds, various parts of a tree and 7_________',NULL,'bulbs',7),(8,2,8,'nests are created in 8_________where eggs are laid.',NULL,'soil',8),(9,2,8,'the 9_________ of the käkāpō were used to make clothes.',NULL,'feathers',9),(10,2,8,'10_________were an animal which they introduced that ate the kākāpō\'s food sources.',NULL,'deer',10),(11,2,8,'a definite sighting of female kākāpō on Rakiura Island was reported in the year 11_________',NULL,'1980',11),(12,2,8,'the Recovery Plan included an increase in 12_________',NULL,'funding',12),(13,2,8,'a current goal of the Recovery Plan is to maintain the involvement of 13_________ in kākāpō protection.',NULL,'stakeholders',13),(14,3,5,'reference to the research problems that arise from there being only a few surviving large elms',NULL,'C',14),(15,3,5,'details of a difference of opinion about the value of reintroducing elms to Britain',NULL,'G',15),(16,3,5,'reference to how Dutch elm disease was brought into Britain',NULL,'B',16),(17,3,5,'a description of the conditions that have enabled a location in Britain to escape Dutch elm disease',NULL,'E',17),(18,3,5,'reference to the stage at which young elms become vulnerable to Dutch elm disease',NULL,'C',18),(19,4,6,'If a tree gets infected with Dutch elm disease, the damage rapidly becomes visible.',NULL,'B',19),(20,4,6,'It may be better to wait and see if the mature elms that have survived continue to flourish.',NULL,'A',20),(21,4,6,'There must be an explanation for the survival of some mature elms.',NULL,'B',21),(22,4,6,'We need to be aware that insects carrying Dutch elm disease are not very far away.',NULL,'C',22),(23,4,6,'You understand the effect Dutch elm disease has had when you see evidence of how prominent the tree once was.',NULL,'A',23),(24,5,8,'For hundreds of years, the only tree that was more popular in Britain than elm was 24__________.',NULL,'oak',24),(25,5,8,'Starting in the Bronze Age, many tools were made from elm and people also used it to make weapons. In the 18th century, it was grown to provide wood for boxes and 25__________.',NULL,'flooring',25),(26,5,8,'Due to its strength, elm was often used for mining equipment and the Cutty Sark\'s 26__________ was also constructed from elm.',NULL,'keel',26),(27,6,3,'In the first paragraph, the writer introduces the topic of the text by','{\"A\": \"defining some commonly used terms.\", \"B\": \"questioning a widely held assumption.\", \"C\": \"mentioning a challenge faced by everyone.\", \"D\": \"specifying a situation which makes us most anxious.\"}','C',27),(28,6,3,'What point does the writer make about firefighters in the second paragraph?','{\"A\": \"The regular changes of stress levels in their working lives make them ideal study subjects.\", \"B\": \"The strategies they use to handle stress are of particular interest to researchers.\", \"C\": \"The stressful nature of their job is typical of many public service professions.\", \"D\": \"Their personalities make them especially well-suited to working under stress.\"}','A',28),(29,6,3,'What is the writer doing in the fourth paragraph?','{\"A\": \"explaining their findings\", \"B\": \"justifying their approach\", \"C\": \"setting out their objectives\", \"D\": \"describing their methodology\"}','D',29),(30,6,3,'In the seventh paragraph, the writer describes a mechanism in the brain which','{\"A\": \"enables people to respond more quickly to stressful situations.\", \"B\": \"results in increased ability to control our levels of anxiety.\", \"C\": \"produces heightened sensitivity to indications of external threats.\", \"D\": \"is activated when there is a need to communicate a sense of danger.\"}','C',30),(31,7,6,'At times when they were relaxed, the firefighters usually',NULL,'B',31),(32,7,6,'The researchers noted that when the firefighters were stressed, they',NULL,'G',32),(33,7,6,'When the firefighters were told good news, they always',NULL,'F',33),(34,7,6,'The students\' cortisol levels and heart rates were affected when the researchers',NULL,'E',34),(35,7,6,'In both experiments, negative information was processed better when the subjects',NULL,'D',35),(36,8,2,'The tone of the content we post on social media tends to reflect the nature of the posts in our feeds.',NULL,'YES',36),(37,8,2,'Phones have a greater impact on our stress levels than other electronic media devices.',NULL,'NOT GIVEN',37),(38,8,2,'The more we read about a stressful public event on social media, the less able we are to take the information in.',NULL,'NO',38),(39,8,2,'Stress created by social media posts can lead us to take unnecessary precautions.',NULL,'YES',39),(40,8,2,'Our tendency to be affected by other people\'s moods can be used in a positive way.',NULL,'YES',40),(41,9,8,'look similar to dugongs, but with a differently shaped 1__________',NULL,'tail',1),(42,9,8,'need to use their 2__________ to help to turn their bodies around in order to look sideways',NULL,'flippers',2),(43,9,8,'sense vibrations in the water by means of 3__________ on their skin',NULL,'hairs',3),(44,9,8,'eat mainly aquatic vegetation, such as 4__________',NULL,'seagrasses',4),(45,9,8,'grasp and pull up plants with their 5__________',NULL,'lips',5),(46,9,8,'may regulate the 6__________ of their bodies by using muscles of diaphragm to store air internally',NULL,'buoyancy',6),(47,10,1,'West Indian manatees can be found in a variety of different aquatic habitats.',NULL,'TRUE',7),(48,10,1,'The Florida manatee lives in warmer waters than the Antillean manatee.',NULL,'NOT GIVEN',8),(49,10,1,'The African manatee\'s range is limited to coastal waters between the West African countries of Mauritania and Angola.',NULL,'FALSE',9),(50,10,1,'The extent of the loss of Amazonian manatees in the mid-twentieth century was only revealed many years later.',NULL,'NOT GIVEN',10),(51,10,1,'It is predicted that West Indian manatee populations will fall in the coming decades.',NULL,'TRUE',11),(52,10,1,'The risk to manatees from entanglement and plastic consumption increased significantly in the period 2009-2020.',NULL,'NOT GIVEN',12),(53,10,1,'There is some legislation in place which aims to reduce the likelihood of boat strikes on manatees in Florida.',NULL,'TRUE',13),(54,11,5,'mention of false assumptions about why people procrastinate',NULL,'B',14),(55,11,5,'reference to the realisation that others also procrastinate',NULL,'F',15),(56,11,5,'neurological evidence of a link between procrastination and emotion',NULL,'B',16),(57,12,8,'Many people think that procrastination is the result of 17__________.',NULL,'laziness',17),(58,12,8,'...cause us to feel 18__________ when we think about them.',NULL,'anxious',18),(59,12,8,'...identifying 19__________.',NULL,'threats',19),(60,12,8,'Getting ready to take 20__________ might be a typical example of one such task.',NULL,'exams',20),(61,12,8,'People who are likely to procrastinate tend to be either 21__________ those with low self-esteem.',NULL,'perfectionists',21),(62,12,8,'It\'s often followed by a feeling of 22__________, which worsens our mood and leads to more procrastination.',NULL,'guilt',22),(63,13,3,'Which TWO comparisons between employees who often procrastinate and those who do not are mentioned in the text?','{\"A\": \"Their salaries are lower.\", \"B\": \"The quality of their work is inferior.\", \"C\": \"They don\'t keep their jobs for as long.\", \"D\": \"They don\'t enjoy their working lives as much.\", \"E\": \"They have poorer relationships with colleagues.\"}','A, C',23),(64,13,3,'Which TWO recommendations for getting out of a cycle of procrastination does the writer give?','{\"A\": \"not judging ourselves harshly\", \"B\": \"setting ourselves manageable aims\", \"C\": \"rewarding ourselves for tasks achieved\", \"D\": \"prioritising tasks according to their importance\", \"E\": \"avoiding things that stop us concentrating on our tasks\"}','A, E',24),(65,14,2,'When DeJesus first used ABS, he shared decision-making about strikes with it.',NULL,'NO',27),(66,14,2,'MLB considered it necessary to amend the size of the strike zone when criticisms were received from players.',NULL,'YES',28),(67,14,2,'MLB is keen to justify the money spent on improving the accuracy of ABS\'s calculations.',NULL,'NOT GIVEN',29),(68,14,2,'The hundred-mile-an-hour fastball led to a more exciting style of play.',NULL,'NO',30),(69,14,2,'The differing proposals for alterations to the baseball bat led to fierce debate on Sword\'s team.',NULL,'NOT GIVEN',31),(70,14,2,'ABS makes changes to the shape of the strike zone feasible.',NULL,'YES',32),(71,15,8,'Even after ABS was developed, MLB still wanted human umpires to shout out decisions as they had in their 33__________.',NULL,'F',33),(72,15,8,'The umpire\'s job had, at one time, required a 34__________ about whether a ball was a strike.',NULL,'D',34),(73,15,8,'A ball is considered a strike when the batter does not hit it and it crosses through a 35__________ extending approximately from the batter\'s knee to his chest.',NULL,'H',35),(74,15,8,'In the past, 36__________ over strike calls were not uncommon, but today everyone accepts the complete ban on pushing or shoving the umpire.',NULL,'B',36),(75,15,8,'One difference, however, is that during the first game DeJesus used ABS, strike calls were met with 37__________.',NULL,'G',37),(76,16,3,'What does the writer suggest about ABS in the fifth paragraph?','{\"A\": \"It is bound to make key decisions that are wrong.\", \"B\": \"It may reduce some of the appeal of the game.\", \"C\": \"It will lead to the disappearance of human umpires.\", \"D\": \"It may increase calls for the rules of baseball to be changed.\"}','B',38),(77,16,3,'Morgan Sword says that the introduction of ABS','{\"A\": \"was regarded as an experiment without a guaranteed outcome.\", \"B\": \"was intended to keep up with developments in other sports.\", \"C\": \"was a response to changing attitudes about the role of sport.\", \"D\": \"was an attempt to ensure baseball retained a young audience.\"}','D',39),(78,16,3,'Why does the writer include the views of Noë and Russo?','{\"A\": \"to show that attitudes to technology vary widely\", \"B\": \"to argue that people have unrealistic expectations of sport\", \"C\": \"to indicate that accuracy is not the same thing as enjoyment\", \"D\": \"to suggest that the number of baseball fans needs to increase\"}','C',40),(79,17,8,'People conserved the nutritional value of 1__________, using a method of freezing then drying.',NULL,'potatoes',1),(80,17,8,'2__________ was kept cool by ice during transportation in specially adapted trains.',NULL,'butter',2),(81,17,8,'Two kinds of 3__________ were the first frozen food shipped to England.',NULL,'meat',3),(82,17,8,'quick-freezing methods, so that 4__________ did not spoil the food.',NULL,'crystals',4),(83,17,8,'packaging products with 5__________ so the product was visible.',NULL,'cellophane',5),(84,17,8,'Frozen food became popular because of a shortage of 6__________',NULL,'tin',6),(85,17,8,'A large number of homes now had a 7__________',NULL,'refrigerator',7),(86,18,1,'The ice transportation business made some Boston ship owners very wealthy in the early 1800s.',NULL,'NOT GIVEN',8),(87,18,1,'A disadvantage of the freezing process invented in Australia was that it affected the taste of food.',NULL,'TRUE',9)